import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"权限与脱敏","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/permission.md","filePath":"frontend/permission.md","lastUpdated":1794049926000}`),a={name:`frontend/permission.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="权限与脱敏" tabindex="-1">权限与脱敏 <a class="header-anchor" href="#权限与脱敏" aria-label="Permalink to “权限与脱敏”">​</a></h1><p>本页说明前端如何使用后端下发的权限与字段安全结果，适用于前端开发者。</p><p>安全边界在后端。前端只决定显示哪些内容：没有权限的入口不显示，受保护的字段按后端给出的值显示。隐藏按钮不能代替后端授权。</p><h2 id="权限数据" tabindex="-1">权限数据 <a class="header-anchor" href="#权限数据" aria-label="Permalink to “权限数据”">​</a></h2><p>登录后守卫首次进入时调 <code>auth.permissions</code>，一次取得：</p><table tabindex="0"><thead><tr><th>项</th><th>用途</th></tr></thead><tbody><tr><td><code>permissions</code></td><td>有效权限码（<code>*</code> 已展开为本侧目录的全部码），按钮与页面门控</td></tr><tr><td><code>roles</code></td><td>本侧生效的角色，展示用</td></tr><tr><td><code>menus</code></td><td>按权限裁剪的菜单树，生成侧栏与动态路由</td></tr><tr><td><code>pages</code></td><td>可访问的页面码</td></tr><tr><td><code>isPlatform</code></td><td>是否平台侧</td></tr></tbody></table><p>结果存在 <code>~/stores</code> 的 auth store。刷新令牌后权限清空，下一次导航重取，角色指派的变化随之生效；切换租户、切换激活角色、开始或结束模仿后整页重建（<code>relaunchApp</code>）。</p><h2 id="按钮即操作" tabindex="-1">按钮即操作 <a class="header-anchor" href="#按钮即操作" aria-label="Permalink to “按钮即操作”">​</a></h2><p>一个写动作对应一个操作，门控直接用该操作的权限码，没有另一套按钮码：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> auth</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useAuthStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">can</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;identity.users.create&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 精确匹配，不认通配</span></span></code></pre></div><div class="language-vue" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">XhButton</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> v-if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">can</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;settings.configs.create&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;新建&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">XhButton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>SchemaPage 的 <code>actions[].permission</code>、<code>removePermission</code>、<code>statusPermission</code>、<code>exportPermission</code>、<code>importPermission</code> 直接填权限码。也可以用 <code>~/hooks</code> 的 <code>usePermission()</code>：<code>hasPermission(code | codes)</code>（数组是「或」，单个空串表示不限制）。</p><p>权限码都来自生成的 <code>~/contracts</code>（<code>permissions.ts</code>）：<code>pnpm permissions:check</code> 扫描 <code>permission:</code>、<code>permissions:</code>、<code>can(&#39;…&#39;)</code>、<code>hasPermission(&#39;…&#39;)</code> 里的三段点分字面量，不在契约里即失败。后端改名或删除权限码时，前端引用处在 CI 中报错。</p><h3 id="组合判断" tabindex="-1">组合判断 <a class="header-anchor" href="#组合判断" aria-label="Permalink to “组合判断”">​</a></h3><p>有的入口要同时看两个权限，例如用户页的「分配角色」：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;assignRoles&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;access.roles.assign&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">visible</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">row</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> isOwnSide</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">asRow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(row)) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> auth.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">can</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;access.roles.read&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }</span></span></code></pre></div><p>另一侧的数据（平台看到的租户数据、租户看到的平台数据）通常只读，用 <code>visible</code> 表达。</p><h2 id="权限名称" tabindex="-1">权限名称 <a class="header-anchor" href="#权限名称" aria-label="Permalink to “权限名称”">​</a></h2><p><code>permissionDefinitions</code> 是导出契约时生成的权限码表（码与英文的显示名、说明），只用来核对权限码，不用来显示。界面上的权限名与说明一律取权限目录 <code>permissions.list</code>：后端按请求的 <code>Accept-Language</code> 从各包语言文件取文案。</p><p>授权界面（角色的权限分配、用户直授、套餐白名单、委托与约束规则的候选）直接用目录生成条目，不手写权限树。只拿到权限码的地方（角色详情里的已授与继承权限、委托列表、授权条件）用 access 模块的 <code>usePermissionNames()</code> 换名字（同一界面语言只取一次目录）；不在本侧目录里的码，或没有 <code>access.permissions.read</code> 时，原样显示权限码。</p><h2 id="字段安全与脱敏" tabindex="-1">字段安全与脱敏 <a class="header-anchor" href="#字段安全与脱敏" aria-label="Permalink to “字段安全与脱敏”">​</a></h2><p>后端在投影时已按字段安全规则处理，前端收到的就是处理后的值：</p><table tabindex="0"><thead><tr><th>情况</th><th>前端表现</th></tr></thead><tbody><tr><td>隐藏</td><td>字段为空，列显示占位；非文本字段只能隐藏</td></tr><tr><td>星号 / 部分脱敏 / 哈希 / 固定文本</td><td>原样显示后端给的值</td></tr><tr><td>按受保护字段筛选、排序或关键字搜索</td><td>后端拒绝（<code>ACCESS_DENIED_006</code>），页面提示 <code>detail</code></td></tr><tr><td>修改受保护字段</td><td>交回原值、脱敏值或空值视为没改，后端保留原值；改了只读字段即拒绝（<code>ACCESS_DENIED_007</code>），新建时填写只读字段同样拒绝</td></tr></tbody></table><p>前端不复制字段安全的判定逻辑，也不尝试「还原」打码值。规则在 <code>/access/field-security</code> 管理，见<a href="./../backend/data-permission">数据权限与字段安全</a>。</p><h2 id="数据范围" tabindex="-1">数据范围 <a class="header-anchor" href="#数据范围" aria-label="Permalink to “数据范围”">​</a></h2><p>数据范围同样只在后端生效：列表、详情与批量操作按数据范围收窄，前端收到的是收窄后的结果。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./routing">菜单与路由</a> · <a href="./../backend/permission">后端权限管理</a></li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};